const watchlist = $input.all().map((item) => item.json);
const staticData = $getWorkflowStaticData('global');
staticData.pdufa_watchlist = watchlist;

return [
  {
    json: {
      loaded_count: watchlist.length,
      static_data_key: 'pdufa_watchlist',
      static_data_scope: 'global',
    },
  },
];

const sourceUrl = 'https://checkrare.com/2026-orphan-drugs-pdufa-dates-and-fda-approvals/';

const html = await helpers.httpRequest({
  method: 'GET',
  url: sourceUrl,
  headers: {
    'User-Agent': 'Mozilla/5.0 (compatible; n8n-pre-catalyst-alert-system/1.0)',
    Accept: 'text/html,application/xhtml+xml',
  },
  returnFullResponse: false,
  json: false,
});

if (!html || typeof html !== 'string') {
  throw new Error('PDUFA source fetch returned empty response.');
}

const rows = [...html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map((m) => m[1]);
if (rows.length === 0) {
  throw new Error('No table rows found on source page.');
}

const stripTags = (value) =>
  value
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeDate = (input) => {
  if (!input) return null;
  const cleaned = input.replace(/(st|nd|rd|th)/gi, '').trim();
  const parsed = new Date(cleaned);
  if (Number.isNaN(parsed.getTime())) return null;
  return parsed.toISOString().slice(0, 10);
};

const isDateLike = (value) => Boolean(normalizeDate(value));

const inferActionType = (text) => {
  const upper = (text || '').toUpperCase();
  if (upper.includes('BLA')) return 'BLA';
  if (upper.includes('sNDA')) return 'sNDA';
  if (upper.includes('NDA')) return 'NDA';
  return 'NDA';
};

const inferredTicker = (text) => {
  const m = text.match(/\(([A-Z]{1,5})\)/);
  if (m) return m[1];
  const allCaps = text.match(/\b[A-Z]{2,5}\b/);
  return allCaps ? allCaps[0] : null;
};

const records = [];

for (const rowHtml of rows) {
  const cells = [...rowHtml.matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi)].map((m) => stripTags(m[1]));
  if (cells.length < 2) continue;

  const joined = cells.join(' | ');
  const maybeDate = cells.map(normalizeDate).find(Boolean);
  if (!maybeDate) continue;

  const ticker = inferredTicker(joined) || 'UNKNOWN';

  const textCells = cells
    .map((c) => c.trim())
    .filter((c) => c.length > 0 && !isDateLike(c));

  const drug = textCells[0] || 'Unknown Drug';
  const indication = textCells[1] || 'Unknown Indication';

  records.push({
    ticker,
    drug,
    indication,
    pdufa_date: maybeDate,
    action_type: inferActionType(joined),
    source: 'CheckRare',
  });
}

const today = new Date();
today.setHours(0, 0, 0, 0);

const futureRecords = records.filter((item) => {
  if (!item.pdufa_date) return false;
  const d = new Date(item.pdufa_date);
  d.setHours(0, 0, 0, 0);
  return !Number.isNaN(d.getTime()) && d >= today;
});

if (futureRecords.length === 0) {
  throw new Error('PDUFA scrape returned zero future-dated records.');
}

return futureRecords.map((item) => ({ json: item }));
